package com.citacloud.app.models; import jakarta.persistence.*; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="documentos") public class Documento {@Id @GeneratedValue private UUID id;@Column(name="empresa_id") private UUID empresaId;@ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="paciente_id") private Paciente paciente;private String nombre;private String tipo;private String descripcion;@Column(name="ruta_archivo") private String rutaArchivo;@Column(name="nombre_archivo") private String nombreArchivo;@Column(name="usuario_id") private UUID usuarioId;private LocalDateTime fecha=LocalDateTime.now();public UUID getId(){return id;}public UUID getEmpresaId(){return empresaId;}public void setEmpresaId(UUID v){empresaId=v;}public Paciente getPaciente(){return paciente;}public void setPaciente(Paciente v){paciente=v;}public String getNombre(){return nombre;}public void setNombre(String v){nombre=v;}public String getTipo(){return tipo;}public void setTipo(String v){tipo=v;}public String getDescripcion(){return descripcion;}public void setDescripcion(String v){descripcion=v;}public String getRutaArchivo(){return rutaArchivo;}public void setRutaArchivo(String v){rutaArchivo=v;}public String getNombreArchivo(){return nombreArchivo;}public void setNombreArchivo(String v){nombreArchivo=v;}public UUID getUsuarioId(){return usuarioId;}public void setUsuarioId(UUID v){usuarioId=v;}public LocalDateTime getFecha(){return fecha;}public void setFecha(LocalDateTime v){fecha=v;}}
